        this.advance();
        return { text: num, value: num, valid: false };
      }
      return { text: num, value: num, valid: true };
    }

    // Decimal number: can have . and/or e/E
    if (this.currentChar() === '.') {
      const nextCh = this.peekChar();
      if (nextCh && /[0-9]/.test(nextCh)) {
        num += '.';
        this.advance();
        while (this.currentChar() && /[0-9]/.test(this.currentChar())) {
          num += this.currentChar();
          this.advance();
          if (this.currentChar() === '_' && /[0-9]/.test(this.peekChar())) {
            num += '_';
            this.advance();
          }
        }
      }
    }

    if (this.currentChar() === 'e' || this.currentChar() === 'E') {
      const nextCh = this.peekChar();
      let canContinue = false;

      if (nextCh && /[0-9]/.test(nextCh)) {
        canContinue = true;
      } else if (nextCh && (nextCh === '+' || nextCh === '-')) {
        const afterSign = this.input[this.pos + 2];
        if (afterSign && /[0-9]/.test(afterSign)) {
          canContinue = true;
        }
      }

      if (canContinue) {
        num += this.currentChar();
        this.advance();
        if (this.currentChar() === '+' || this.currentChar() === '-') {
          num += this.currentChar();
          this.advance();
        }
        while (this.currentChar() && /[0-9]/.test(this.currentChar())) {
          num += this.currentChar();
          this.advance();
          if (this.currentChar() === '_' && /[0-9]/.test(this.peekChar())) {
            num += '_';
            this.advance();
          }
        }
      }
    }

    // Check for invalid trailing characters
    if (this.currentChar() && /[a-zA-Z0-9_]/.test(this.currentChar())) {
      const invalid = this.currentChar();
      num += invalid;
      this.advance();
      return { text: num, value: num, valid: false };
    }

    return { text: num, value: num, valid: true };
  }

  readIdentifier() {
    let ident = '';
    while (this.currentChar() && /[a-zA-Z0-9_]/.test(this.currentChar())) {
      ident += this.currentChar();
      this.advance();
    }
    return ident;
  }

  scan() {
    while (this.currentChar()) {
      this.skipWhitespace();
      if (!this.currentChar()) break;

      const ch = this.currentChar();
      const line = this.line;
      const col = this.column;

      // Line comment
      if (ch === '/' && this.peekChar() === '/') {
        this.skipLineComment();
        continue;
      }

      // Block comment
      if (ch === '/' && this.peekChar() === '*') {
        if (!this.skipBlockComment()) {
          return false;
        }
        continue;
      }

      // String
      if (ch === '"') {
        const value = this.readString();
        if (value === null) return false;
        this.tokens.push({
          kind: 'string',
          line,
          column: col,
          body: JSON.stringify(value)
        });
        continue;
      }

      // Raw string
      if (ch === 'r' && this.peekChar() === '"') {
        const value = this.readRawString();
        if (value === null) return false;
        this.tokens.push({
          kind: 'rawstring',
          line,
          column: col,
          body: JSON.stringify(value)
        });
        continue;
      }

      // Number
      if (/[0-9]/.test(ch)) {
        const { text, valid } = this.readNumber();
        if (!valid) {
          this.errors.push({
            line,
            column: col,
            message: `invalid number ${text}`
          });
          return false;
        }
        this.tokens.push({
          kind: 'number',
          line,
          column: col,
          body: text
        });
        continue;
      }

      // Identifier or keyword
      if (/[a-zA-Z_]/.test(ch)) {
        const ident = this.readIdentifier();
        const kind = KEYWORDS.has(ident) ? 'keyword' : 'ident';
        this.tokens.push({
          kind,
          line,
          column: col,
          body: ident
        });
        continue;
      }

      // Punctuation (try 2-char first)
      const twoChar = ch + this.peekChar();
      if (PUNCT_2CHAR.has(twoChar)) {
        this.advance();
        this.advance();
        this.tokens.push({
          kind: 'punct',
          line,
          column: col,
          body: twoChar
        });
        continue;
      }

      // Punctuation (1-char)
      if (PUNCT_1CHAR.has(ch)) {
        this.advance();
        this.tokens.push({
          kind: 'punct',
          line,
          column: col,
          body: ch
        });
        continue;
      }

      // Unexpected character
      this.errors.push({
        line,
        column: col,
        message: `unexpected character ${ch}`
      });
      return false;
    }

    return true;
  }

  getTokens() {
    return this.tokens;
  }

  getErrors() {
    return this.errors;
  }
}
"}

