/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { Scanner } from './scanner.js';
import { readFileSync } from 'fs';

// Check arguments
const args = process.argv.slice(2);
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n');
  process.exit(2);
}

const mode = args[0];

// Read stdin
let input = '';
try {
  input = readFileSync(0, 'utf8');
} catch (e) {
  // readFileSync(0) should work on stdin
  process.stderr.write('error: failed to read input\n');
  process.exit(2);
}

// Scan
const scanner = new Scanner(input);
const success = scanner.scan();

if (!success) {
  const errors = scanner.getErrors();
  if (errors.length > 0) {
    const error = errors[0];
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.message}\n`);
  }
  process.exit(2);
}

const tokens = scanner.getTokens();

if (mode === 'tokens') {
  for (const token of tokens) {
    process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`);
  }
} else if (mode === 'stats') {
  const counts = {
    ident: 0,
    keyword: 0,
    number: 0,
    punct: 0,
    rawstring: 0,
    string: 0
  };

  for (const token of tokens) {
    counts[token.kind]++;
  }

  const total = tokens.length;
  process.stdout.write(`ident ${counts.ident}\n`);
  process.stdout.write(`keyword ${counts.keyword}\n`);
  process.stdout.write(`number ${counts.number}\n`);
